import {normalizeDesktopGamepad} from './desktop-input.js';
export function createProjectedShieldControl({getGame,canControl=()=>true}={}){
 if(typeof document==='undefined')return{sync(){},dispose(){}};
 if(!document.getElementById('pw-projected-shield-style')){
  const style=document.createElement('style');style.id='pw-projected-shield-style';style.textContent=`
  #pw-projected-shield{position:fixed;right:var(--pw-right,max(16px,env(safe-area-inset-right)));bottom:calc(env(safe-area-inset-bottom) + 110px);z-index:24;box-sizing:border-box;display:grid;place-items:center;width:56px;height:56px;min-width:56px;min-height:56px;margin:0;padding:9px;border:1px solid var(--shield-accent,#ff80b2);border-radius:50%;color:#edf5ff;background:linear-gradient(145deg,#dcefff22,#20354a88),#102332e8;box-shadow:inset 0 1px #ffffff40,0 3px 16px #0006;pointer-events:auto;touch-action:manipulation;user-select:none;-webkit-user-select:none}
  #pw-projected-shield svg{width:28px;height:30px;fill:none;stroke:var(--shield-accent,#ff80b2);stroke-width:1.7;pointer-events:none}
  #pw-projected-shield .pw-shield-count{position:absolute;right:-4px;top:-5px;min-width:22px;height:22px;padding:0 3px;box-sizing:border-box;display:grid;place-items:center;border:1px solid var(--shield-accent);border-radius:12px;color:#fff;background:#17283af5;font:800 10px/1 system-ui;pointer-events:none}
  #pw-projected-shield kbd{position:absolute;left:-5px;bottom:-3px;padding:3px 5px;border:1px solid #ffffff55;border-radius:5px;background:#102332;font:700 9px system-ui;pointer-events:none}
  #pw-projected-shield::before{content:'';position:absolute;inset:-4px;border-radius:50%;background:conic-gradient(var(--shield-accent) calc(var(--shield-charge,1)*1turn),#ffffff12 0);mask:radial-gradient(farthest-side,transparent calc(100% - 2px),#000 0);-webkit-mask:radial-gradient(farthest-side,transparent calc(100% - 2px),#000 0);pointer-events:none}
  #pw-projected-shield[aria-pressed=true]{background:color-mix(in srgb,var(--shield-accent) 30%,#102332);box-shadow:inset 0 1px #ffffff50,0 0 18px color-mix(in srgb,var(--shield-accent) 40%,transparent)}
  #pw-projected-shield[aria-pressed=true] svg{fill:color-mix(in srgb,var(--shield-accent) 20%,transparent)}
  #pw-projected-shield:focus-visible{outline:2px solid #fff;outline-offset:7px}#pw-projected-shield:disabled{opacity:.45}#pw-projected-shield[hidden]{display:none!important}
  @media(pointer:coarse){#pw-projected-shield{right:calc(var(--pw-right,max(16px,env(safe-area-inset-right))) + 80px);bottom:calc(var(--pw-stick-bottom,max(28px,env(safe-area-inset-bottom))) + 163px)}#pw-projected-shield kbd{display:none}}
  @media(pointer:coarse) and (orientation:landscape) and (max-height:540px){#pw-projected-shield{right:calc(var(--pw-right,max(16px,env(safe-area-inset-right))) + 67px);bottom:calc(var(--pw-stick-bottom,max(25px,env(safe-area-inset-bottom))) + 133px);width:48px;height:48px;min-width:48px;min-height:48px;padding:8px}#pw-projected-shield svg{width:25px;height:27px}}
  body.xr-mode #pw-projected-shield,body.in-xr #pw-projected-shield,body.stereo-mode #pw-projected-shield{display:none!important}`;
  document.head.append(style);
 }
 const button=document.createElement('button');button.id='pw-projected-shield';button.type='button';button.className='pw-hud-shield-direct pw-glass';button.hidden=true;button.innerHTML='<svg viewBox="0 0 24 28" aria-hidden="true"><path d="M12 2 22 6v9c0 5-5 9-10 11C7 24 2 20 2 15V6Z"/><path d="m7 14 3 3 7-8"/></svg><span class="pw-shield-count" aria-hidden="true"></span><kbd aria-hidden="true">H</kbd>';document.body.append(button);
 let disposed=false,frame=0,pads=new Map();
 const hud=()=>document.querySelector('.pw-hud');
 const active=()=>{const g=getGame?.(),root=hud();return !!(g?.projectedShieldsEnabled&&g.state==='playing'&&g.player.hp>0&&canControl()&&!document.hidden&&!document.querySelector('dialog[open]')&&!(root?.hidden||root?.classList.contains('pw-gear-open'))&&!document.body.matches('.xr-mode,.in-xr'));};
 const toggle=()=>{if(active())getGame().toggleProjectedShield();sync();};
 const key=e=>{if(e.code!=='KeyH'||e.repeat||e.ctrlKey||e.metaKey||e.altKey||/^(INPUT|TEXTAREA|SELECT)$/.test(e.target?.tagName)||e.target?.isContentEditable)return;if(active()){e.preventDefault();toggle();}};
 const pointer=e=>{e.preventDefault();e.stopPropagation();toggle();};button.addEventListener('pointerdown',pointer);button.addEventListener('click',e=>{if(e.detail===0)toggle();});window.addEventListener('keydown',key);
 function sync(){const g=getGame?.(),root=hud();if(root&&button.parentNode!==root)root.append(button);button.hidden=!active();if(!g)return;button.style.setProperty('--shield-accent',g.characterId==='lylu'?'#79bbff':'#ff80b2');button.style.setProperty('--shield-charge',String(Math.max(0,Math.min(1,(g.player.shield||0)/(g.shieldCapacity||60)))));button.disabled=(g.player.shield||0)<=0;button.setAttribute('aria-pressed',String(!!g.player.shieldDeployed));const label=button.disabled?'Bouclier en recharge':g.player.shieldDeployed?'Replier le bouclier':'Déployer le bouclier';button.setAttribute('aria-label',label+' · '+Math.ceil(g.player.shield)+' points');button.title=label+' · H · Manette : croix directionnelle ↓';button.querySelector('.pw-shield-count').textContent=Math.ceil(g.player.shield);}
 function poll(){if(disposed)return;const next=new Map();for(const pad of navigator.getGamepads?.()||[]){if(!pad||pad.mapping==='xr-standard')continue;const normalized=normalizeDesktopGamepad(pad);if(!normalized)continue;const down=!!normalized.buttons[13]?.pressed;next.set(pad.index,down);if(down&&!pads.get(pad.index)&&active())toggle();}pads=next;sync();frame=requestAnimationFrame(poll);}frame=requestAnimationFrame(poll);
 return{sync,dispose(){disposed=true;cancelAnimationFrame(frame);window.removeEventListener('keydown',key);button.remove();pads.clear();}};
}
